drop extension if exists "pg_net";


  create table "public"."friendships" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "status" character varying not null default 'pending'::character varying,
    "requester_id" uuid not null,
    "addressee_id" uuid not null,
    "restrictions" jsonb
      );


alter table "public"."friendships" enable row level security;


  create table "public"."messages" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "deleted_at" timestamp with time zone,
    "thread_id" uuid not null,
    "user_id" uuid,
    "content" character varying not null,
    "metadata" jsonb,
    "message_type" character varying default 'text'::character varying
      );


alter table "public"."messages" enable row level security;

alter table "public"."roadmaps" add column "anchor_id" uuid;

alter table "public"."thread_participants" enable row level security;

alter table "public"."threads" enable row level security;

CREATE UNIQUE INDEX friendships_pkey ON public.friendships USING btree (id);

CREATE UNIQUE INDEX messages_pkey ON public.messages USING btree (id);

alter table "public"."friendships" add constraint "friendships_pkey" PRIMARY KEY using index "friendships_pkey";

alter table "public"."messages" add constraint "messages_pkey" PRIMARY KEY using index "messages_pkey";

alter table "public"."friendships" add constraint "friendships_addressee_id_fkey" FOREIGN KEY (addressee_id) REFERENCES users(user_id) not valid;

alter table "public"."friendships" validate constraint "friendships_addressee_id_fkey";

alter table "public"."friendships" add constraint "friendships_requester_id_fkey" FOREIGN KEY (requester_id) REFERENCES users(user_id) not valid;

alter table "public"."friendships" validate constraint "friendships_requester_id_fkey";

alter table "public"."messages" add constraint "messages_thread_id_fkey" FOREIGN KEY (thread_id) REFERENCES threads(thread_id) not valid;

alter table "public"."messages" validate constraint "messages_thread_id_fkey";

alter table "public"."messages" add constraint "messages_user_id_fkey" FOREIGN KEY (user_id) REFERENCES users(user_id) not valid;

alter table "public"."messages" validate constraint "messages_user_id_fkey";

alter table "public"."roadmaps" add constraint "roadmaps_anchor_id_fkey" FOREIGN KEY (anchor_id) REFERENCES users(user_id) not valid;

alter table "public"."roadmaps" validate constraint "roadmaps_anchor_id_fkey";

